import{_ as r,o,c as a,a2 as s}from"./chunks/framework.CXsxtpvq.js";const n="/asset-studio/shots/10-lab-empty.webp",u=JSON.parse('{"title":"실험실","description":"","frontmatter":{},"headers":[],"relativePath":"ko/guide/lab.md","filePath":"ko/guide/lab.md"}'),e={name:"ko/guide/lab.md"};function l(d,t,i,g,h,p){return o(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="실험실" tabindex="-1">실험실 <a class="header-anchor" href="#실험실" aria-label="Permalink to &quot;실험실&quot;">​</a></h1><p><strong>실험실</strong>은 라이브러리와 상관없이 프롬프트 하나를 자유롭게 시험하는 곳입니다. 시드를 바꿔 보거나 설정값 하나만 바꿔 가며 결과를 나란히 비교합니다. 결과는 <code>outputs/_lab/&lt;날짜&gt;/</code>에 저장되고 갤러리에도 보입니다.</p><p><img src="'+n+'" alt="실험실"></p><h2 id="프롬프트와-생성-설정" tabindex="-1">프롬프트와 생성 설정 <a class="header-anchor" href="#프롬프트와-생성-설정" aria-label="Permalink to &quot;프롬프트와 생성 설정&quot;">​</a></h2><ul><li><strong>프롬프트</strong> / <strong>제외 프롬프트</strong>: 직접 적습니다. 태그 자동완성이 됩니다. <strong>긍정 태그 확인</strong> / <strong>제외 태그 확인</strong>은 Danbooru에 없는 태그를 알려 줍니다.</li><li><strong>생성 설정</strong>: 작업 화면과 같은 설정입니다. <strong>프리셋 불러오기</strong>로 저장해 둔 생성 프리셋을 불러오고, <strong>현재 설정을 프리셋으로 저장</strong>으로 새 프리셋을 만듭니다.</li></ul><p>다른 곳에서 넘겨받을 수도 있습니다.</p><ul><li>작업 화면 미리보기의 <strong>실험실에서 열기</strong></li><li>갤러리 이미지 상세의 <strong>실험실에서 열기</strong></li><li>이미지 도구의 <strong>실험실에서 열기</strong>, <strong>태그로 실험실 열기</strong></li></ul><p>넘겨받으면 위쪽에 <strong>가져온 곳</strong>이 표시됩니다.</p><h2 id="시드-비교" tabindex="-1">시드 비교 <a class="header-anchor" href="#시드-비교" aria-label="Permalink to &quot;시드 비교&quot;">​</a></h2><p><strong>시드 수</strong>만큼 시드를 바꿔 생성합니다. 같은 프롬프트가 얼마나 안정적으로 나오는지 볼 때 씁니다.</p><h2 id="값-비교" tabindex="-1">값 비교 <a class="header-anchor" href="#값-비교" aria-label="Permalink to &quot;값 비교&quot;">​</a></h2><p><strong>바꿔 볼 값</strong>에서 항목 하나를 고르고 <strong>값 목록</strong>에 비교할 값을 쉼표로 적습니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>값 예</th></tr></thead><tbody><tr><td>CFG</td><td>3, 4.5, 6</td></tr><tr><td>Steps</td><td>20, 28, 36</td></tr><tr><td>샘플러 · 스케줄러</td><td>비우면 목록 전체</td></tr><tr><td>CLIP skip (SDXL)</td><td>1, 2</td></tr><tr><td>LoRA 강도</td><td>0.4, 0.7, 1.0</td></tr></tbody></table><p>시드 수 × 값 개수만큼 생성됩니다(화면에 <code>시드 2개 × 값 3개 = 6장</code>처럼 표시).</p><h2 id="결과-비교" tabindex="-1">결과 비교 <a class="header-anchor" href="#결과-비교" aria-label="Permalink to &quot;결과 비교&quot;">​</a></h2><p>결과에서 두 장을 골라 <strong>기준</strong>과 <strong>비교</strong>로 놓고 봅니다.</p><ul><li><strong>나란히</strong>: 두 장을 옆에 놓습니다.</li><li><strong>슬라이더</strong>: 한 장 위에 다른 장을 겹치고 경계를 끌어 차이를 봅니다.</li><li><strong>기준↔비교 바꾸기</strong>, <strong>비교 이미지 설정 불러오기</strong>(마음에 든 쪽의 설정을 폼으로 가져옴)를 쓸 수 있습니다.</li></ul>',17)])])}const _=r(e,[["render",l]]);export{u as __pageData,_ as default};
